import {poseBaseballTiger} from './baseball-tiger.js';
import {poseAthleticTurtle} from './athletic-turtle.js';
import {poseAthleticRabbit} from './athletic-rabbit.js';
// One owner temporarily borrows an existing resident. No character is cloned.
export function installResidentActivityLease(view,models,{getTime,setTime}){
 view.acquireResidentActivity=id=>{const r=view.residents?.residents.find(r=>r.id===id),model=models.get(id);if(!['athletic-turtle','athletic-rabbit','baseball-tiger'].includes(id)||!r||!model||r.activityLease)return null;const savedRecord={...r},time=getTime(),nodes=[],geometries=[];model.traverse(n=>{nodes.push({node:n,position:n.position.clone(),quaternion:n.quaternion.clone(),scale:n.scale.clone(),visible:n.visible});if(n.geometry?.attributes?.position)geometries.push({geometry:n.geometry,position:n.geometry.attributes.position.array.slice(),normal:n.geometry.attributes.normal?.array.slice()});});let alive=true;r.activityLease=true;
  return{model,pose({x,y=.04,z,yaw=-Math.PI/2,time=0,walking=false,running=false,holding=true,showBall=false,pitchPhase=null}){if(!alive||![x,y,z,yaw].every(Number.isFinite))return false;r.x=x;r.z=z;r.yaw=yaw;r.moving=false;model.position.set(x,y,z);model.rotation.set(0,yaw,0);if(id==='baseball-tiger'){poseBaseballTiger(model,{time,walking,pitchPhase});model.userData.parts.Ball.visible=showBall;}else if(id==='athletic-rabbit'){poseAthleticRabbit(model,{time,walking,running,holding});model.userData.parts.Ball.visible=showBall;}else poseAthleticTurtle(model,{time,lifting:false,walking,showBarbell:false});return true;},release(){if(!alive)return;alive=false;delete r.activityLease;Object.assign(r,savedRecord);setTime(time);for(const n of nodes){n.node.position.copy(n.position);n.node.quaternion.copy(n.quaternion);n.node.scale.copy(n.scale);n.node.visible=n.visible;}for(const g of geometries){g.geometry.attributes.position.array.set(g.position);g.geometry.attributes.position.needsUpdate=true;if(g.normal){g.geometry.attributes.normal.array.set(g.normal);g.geometry.attributes.normal.needsUpdate=true;}g.geometry.computeBoundingBox();g.geometry.computeBoundingSphere();}model.updateMatrixWorld(true);}};
 };
}
